CREATE DATABASE IF NOT EXISTS crust_and_crumb CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE crust_and_crumb;

CREATE TABLE roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL DEFAULT 1, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(30), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, sort_order SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL, image_url VARCHAR(500), stock_quantity INT NOT NULL DEFAULT 0, minimum_order_quantity INT NOT NULL DEFAULT 1, preorder_enabled BOOLEAN NOT NULL DEFAULT TRUE, pickup_enabled BOOLEAN NOT NULL DEFAULT TRUE, delivery_enabled BOOLEAN NOT NULL DEFAULT FALSE, is_featured BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_products_active (is_active, category_id), FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE ingredients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE allergens (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE product_ingredients (product_id INT UNSIGNED NOT NULL, ingredient_id INT UNSIGNED NOT NULL, PRIMARY KEY(product_id, ingredient_id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(ingredient_id) REFERENCES ingredients(id) ON DELETE CASCADE);
CREATE TABLE product_allergens (product_id INT UNSIGNED NOT NULL, allergen_id INT UNSIGNED NOT NULL, PRIMARY KEY(product_id, allergen_id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(allergen_id) REFERENCES allergens(id) ON DELETE CASCADE);
CREATE TABLE fresh_today (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, fresh_date DATE NOT NULL, batch_time TIME NOT NULL, quantity_available INT NOT NULL DEFAULT 0, status ENUM('available','sold_out','hidden') NOT NULL DEFAULT 'available', special_note VARCHAR(180), UNIQUE KEY unique_fresh_product_date (product_id, fresh_date), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE pickup_slots (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slot_date DATE NOT NULL, starts_at TIME NOT NULL, ends_at TIME NOT NULL, max_orders SMALLINT UNSIGNED NOT NULL DEFAULT 10, booked_orders SMALLINT UNSIGNED NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY unique_slot (slot_date, starts_at));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED, order_number VARCHAR(30) NOT NULL UNIQUE, fulfillment_method ENUM('pickup','delivery') NOT NULL, status ENUM('pending','confirmed','preparing','ready_for_pickup','collected','out_for_delivery','delivered','cancelled') NOT NULL DEFAULT 'pending', payment_status ENUM('pending','paid','failed','refunded','cancelled') NOT NULL DEFAULT 'pending', customer_name VARCHAR(120) NOT NULL, customer_email VARCHAR(190) NOT NULL, customer_phone VARCHAR(30) NOT NULL, pickup_slot_id INT UNSIGNED, delivery_address TEXT, subtotal DECIMAL(10,2) NOT NULL, delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(pickup_slot_id) REFERENCES pickup_slots(id) ON DELETE SET NULL, INDEX idx_orders_status_date (status, created_at));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(150) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, line_total DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE cake_quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED, cake_type VARCHAR(80) NOT NULL, size VARCHAR(40) NOT NULL, tiers VARCHAR(20) NOT NULL, filling VARCHAR(80), frosting VARCHAR(80), decoration VARCHAR(80), message VARCHAR(255), event_date DATE NOT NULL, guest_count SMALLINT UNSIGNED, reference_image VARCHAR(255), estimated_total DECIMAL(10,2) NOT NULL DEFAULT 0, final_total DECIMAL(10,2), status ENUM('pending','quoted','accepted','rejected','converted') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE catering_quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED, event_type VARCHAR(100) NOT NULL, event_date DATE NOT NULL, location VARCHAR(180) NOT NULL, guest_count INT UNSIGNED NOT NULL, budget_range VARCHAR(80), requirements TEXT, dietary_requirements TEXT, allergies TEXT, delivery_required BOOLEAN DEFAULT FALSE, special_instructions TEXT, quoted_total DECIMAL(10,2), status ENUM('pending','quoted','accepted','rejected','converted') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
